CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE TYPE "TransactionStatus" AS ENUM ('PENDING','PROCESSING','COMPLETED','FAILED','REVERSED');
CREATE TABLE idempotency_keys (key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'processing', response_body JSONB, transaction_id UUID UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+interval '24 hours'); CREATE INDEX idx_idempotency_expires ON idempotency_keys(expires_at);
CREATE TABLE transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL UNIQUE REFERENCES idempotency_keys(key), request_hash TEXT NOT NULL, sender_wallet_id UUID NOT NULL, recipient_wallet_id UUID NOT NULL, amount_cents BIGINT NOT NULL CHECK(amount_cents>0), currency CHAR(3) NOT NULL, destination_amount_cents BIGINT, destination_currency CHAR(3), fx_rate NUMERIC(18,8), fx_quote_id UUID, status "TransactionStatus" NOT NULL DEFAULT 'PENDING', processing_started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, failure_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX idx_transactions_status ON transactions(status); CREATE INDEX idx_transactions_sender ON transactions(sender_wallet_id); CREATE INDEX idx_transactions_recipient ON transactions(recipient_wallet_id); CREATE INDEX idx_transactions_created ON transactions(created_at);
